/**
 * @name Potential code injection through wrapper/decorator execution
 * @description Wrapt package handles function wrapping and decorators which could potentially execute untrusted code
 * @kind path-problem
 * @problem.severity high
 * @id py/wrapt-code-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module WraptInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to exec, eval, or other code execution in wrapt modules
    sink instanceof CodeExecution or
    // Also check for function calls that might execute wrapped functions
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("wrapt").getMember(["wrap", "wrapper", "FunctionWrapper"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module WraptInjectionFlow = TaintTracking::Global<WraptInjectionConfig>;
import WraptInjectionFlow::PathGraph

from WraptInjectionFlow::PathNode source, WraptInjectionFlow::PathNode sink
where WraptInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential code injection through wrapt wrapper from $@.", source.getNode(), "user input"

/**
 * @name Dynamic import with user input flow
 * @description Dynamic import operations that could be influenced by untrusted input
 * @kind path-problem
 * @problem.severity medium
 * @id py/dynamic-import-taint
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module DynamicImportConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for dynamic imports: __import__, importlib.import_module, exec, eval
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("__import__").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("importlib").getMember("import_module").getACall() and
      sink = call.getArg(0)
    ) or
    exists(DataFlow::CallCfgNode call |
      call = API::builtin(["exec", "eval"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module DynamicImportFlow = TaintTracking::Global<DynamicImportConfig>;
import DynamicImportFlow::PathGraph

from DynamicImportFlow::PathNode source, DynamicImportFlow::PathNode sink
where DynamicImportFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Dynamic import with potentially untrusted input from $@.", source.getNode(), "user input"

/**
 * @name Code injection via exec in wrapt.decorators
 * @description Tracing user input to exec() call in wrapt.decorators module
 * @kind path-problem
 * @problem.severity high
 * @id py/wrapt-exec-injection
 * @tags security
 *        external/cwe/cwe-094
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts
import semmle.python.ApiGraphs

module ExecInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Specifically target the exec() call in decorators.py
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("exec").getACall() and
      sink = call.getArg(0) and
      // Use getLocation() to get file information instead of getFile()
      call.getLocation().getFile().getBaseName() = "decorators.py"
    )
  }
}

module ExecInjectionFlow = TaintTracking::Global<ExecInjectionConfig>;
import ExecInjectionFlow::PathGraph

from ExecInjectionFlow::PathNode source, ExecInjectionFlow::PathNode sink
where ExecInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Code injection via exec() from $@.", source.getNode(), "user input"
